#include "PrinterDiscovery.hpp"
#include "libslic3r/AppConfig.hpp"

#include "slic3r/GUI/DeviceCore/DevBed.h"
#include "slic3r/GUI/DeviceCore/DevExtruderSystem.h"
#include "slic3r/GUI/DeviceCore/DevFilaSystem.h"
#include "slic3r/GUI/DeviceCore/DevManager.h"
#include "slic3r/GUI/GUI_App.hpp"

#include <algorithm>
#include <chrono>

namespace Slic3r::GUI::JusPrin::PrinterSetup {

namespace {

// "#RRGGBB", or empty when the tray reported no colour: upstream decodes a
// missing colour as white, which would draw a white spool nobody loaded.
std::string reported_colour(const DevAmsTray& tray)
{
    return tray.color.empty() ? std::string() : std::string(tray.get_color().GetAsString(wxC2S_HTML_SYNTAX).ToUTF8());
}

// The nozzle and the loaded spools, as the device last reported them. The
// plate is not among them: MachineObject carries no build-plate type.
void read_reported_hardware(MachineObject& machine, DiscoveredPrinter& printer)
{
    if (const DevExtderSystem* extruders = machine.GetExtderSystem()) {
        printer.nozzle_diameter = extruders->GetNozzleDiameter(0);
        if (extruders->GetTotalExtderCount() > 0 && machine.is_connected())
            printer.nozzle_temperature = extruders->GetNozzleTempCurrent(0);
    }
    if (DevBed* bed = machine.GetBed(); bed != nullptr && machine.is_connected())
        printer.bed_temperature = bed->GetBedTemp();
    if (machine.is_in_printing()) {
        printer.progress_percent = machine.mc_print_percent;
        printer.job              = machine.subtask_name;
    }
    DevFilaSystem* filaments = machine.GetFilaSystem();
    if (!filaments) return;
    for (const auto& [ams_id, ams] : filaments->GetAmsList()) {
        if (!ams) continue;
        if (printer.ams_name.empty())
            printer.ams_name = ams->GetAmsType() == DevAms::AMS_LITE ? "AMS lite" : "AMS";
        for (const auto& [tray_id, tray] : ams->GetTrays()) {
            if (!tray || !tray->is_exists) continue;
            const std::string material = tray->sub_brands.empty() ? tray->get_display_filament_type() : tray->sub_brands;
            if (material.empty()) continue;
            printer.spools.push_back({(tray->is_bbl ? "Bambu " : "") + material, reported_colour(*tray),
                                      tray->get_display_filament_type()});
        }
    }
    // The external spool holder, which a printer without an AMS feeds from.
    for (const DevAmsTray& tray : machine.vt_slot) {
        if (!tray.is_exists || tray.get_display_filament_type().empty()) continue;
        const std::string material = tray.sub_brands.empty() ? tray.get_display_filament_type() : tray.sub_brands;
        printer.spools.push_back({(tray.is_bbl ? "Bambu " : "") + material, reported_colour(tray),
                                  tray.get_display_filament_type()});
    }
}

} // namespace

bool has_verified_printer_connection(const std::string& device_id)
{
    return !device_id.empty() && wxGetApp().app_config->get("jusprin_verified_connections", device_id) == "true";
}

bool has_recent_printer_data(MachineObject& machine)
{
    const auto observed = machine.is_lan_mode_printer() ? machine.last_lan_msg_time_ : machine.last_cloud_msg_time_;
    return machine.m_push_count > 0 && machine.is_connected() &&
           std::chrono::system_clock::now() - observed < std::chrono::seconds(30);
}

std::vector<DiscoveredPrinter> discover_printers(bool include_unreachable)
{
    std::vector<DiscoveredPrinter> result;
    DeviceManager* devices = wxGetApp().getDeviceManager();
    if (!devices) return result;
    const MachineObject* selected = devices->get_selected_machine();
    for (const auto& [id, machine] : devices->get_my_machine_list()) {
        if (!machine) continue;
        const bool reachable = machine->is_online() || machine->is_connected();
        if (!reachable && !include_unreachable) continue;
        DiscoveredPrinter printer{id, machine->get_dev_name(), machine->get_dev_ip(), machine->printer_type,
                                  machine->connection_type(), has_recent_printer_data(*machine)};
        // Upstream's own predicate, never a copy of it: the list of states that
        // count as printing has been got wrong here before.
        printer.activity = !printer.connected              ? PrinterActivity::Offline :
                           machine->is_in_printing()        ? PrinterActivity::Printing :
                                                              PrinterActivity::Idle;
        if (machine->last_update_time.time_since_epoch().count() != 0)
            printer.observed_at_ms = std::chrono::duration_cast<std::chrono::milliseconds>(
                                         machine->last_update_time.time_since_epoch())
                                         .count();
        printer.selected = machine == selected;
        read_reported_hardware(*machine, printer);
        result.push_back(std::move(printer));
    }
    std::sort(result.begin(), result.end(), [](const DiscoveredPrinter& a, const DiscoveredPrinter& b) {
        if (a.connected != b.connected) return a.connected > b.connected;
        if (a.name != b.name) return a.name < b.name;
        return a.stable_id < b.stable_id;
    });
    return result;
}

} // namespace Slic3r::GUI::JusPrin::PrinterSetup
#pragma once

#include "PrinterSetupTypes.hpp"

#include <vector>

namespace Slic3r { class MachineObject; }

namespace Slic3r::GUI::JusPrin::PrinterSetup {

// Snapshots device fields on the GUI thread. No MachineObject pointer crosses
// the boundary into the dialog/controller.
//
// Printers the app has not heard from are left out by default, because setup
// offers what can be connected to now. A caller reporting what the app knows,
// rather than what it can offer, asks for them.
std::vector<DiscoveredPrinter> discover_printers(bool include_unreachable = false);
bool has_recent_printer_data(MachineObject& machine);
// Device identity/credentials alone do not establish a previous successful connection.
bool has_verified_printer_connection(const std::string& device_id);

} // namespace Slic3r::GUI::JusPrin::PrinterSetup
#pragma once

#include "PrinterBackend.hpp"
#include "PrinterSetupTypes.hpp"

#include <string>
#include <utility>
#include <vector>

namespace Slic3r::GUI::JusPrin::PrinterSetup {

// A printer profile's name as brand and model: {"Bambu Lab", "A1 mini"} for
// "Bambu Lab A1 mini" under the vendor file "Bambulab". A name that does not
// start with its brand keeps the vendor's name as the brand and is the model
// whole.
std::pair<std::string, std::string> split_brand(const std::string& vendor_name, const std::string& profile_name);

class PrinterCatalog
{
public:
    // Reads the packaged profile indexes. It never reads or changes the user's
    // installed presets, which makes opening the flow side-effect free.
    static PrinterCatalog load(const std::string& resources_directory);

    explicit PrinterCatalog(std::vector<PrinterCandidate> candidates = {});

    const std::vector<PrinterCandidate>& candidates() const { return m_candidates; }
    const PrinterCandidate* find(const std::string& id) const;
    const PrinterCandidate* find_device_model(const std::string& device_model_id) const;

    // One entry per printer model, which is what recognition is asked to name:
    // the 0.4 mm variant where the model ships one, otherwise its first.
    std::vector<const PrinterCandidate*> models() const;

    // The printers the printer panel offers: one per model, with the nozzle
    // sizes it ships and each size's default filament, in catalogue order.
    // The Orca Arena bundle is left out (it stays in OrcaSlicer's wizard).
    std::vector<CatalogPrinter> panel_printers() const;

private:
    std::vector<PrinterCandidate> m_candidates;
};

} // namespace Slic3r::GUI::JusPrin::PrinterSetup
#pragma once

#include <cstdint>
#include <optional>
#include <string>
#include <vector>

namespace Slic3r::GUI::JusPrin::PrinterSetup {

// What a printer is doing, as far as this application can see. Offline is a
// statement about what was observed, not a claim that the machine is off.
enum class PrinterActivity : std::uint8_t { Offline, Idle, Printing };

struct DiscoveredPrinter
{
    std::string stable_id;
    std::string name;
    std::string ip_address;
    std::string device_model_id;
    std::string connection;
    bool connected{false};
    PrinterActivity activity{PrinterActivity::Offline};
    // When the device last said anything, as milliseconds since the epoch.
    // Zero when it never has: a printer known from a previous session but not
    // heard from since is a real state, and a fabricated timestamp is not.
    std::int64_t observed_at_ms{0};
    // What the printer reported about itself; zero or empty when it has not said.
    double nozzle_diameter{0.};
    std::string ams_name;
    struct Spool
    {
        std::string name;
        std::string colour;   // "#RRGGBB"
        std::string material; // the filament type, such as PLA; may be empty
    };
    std::vector<Spool> spools;
    // The machine the app is working with, as Orca's device manager has it.
    bool selected{false};
    // The job in progress; -1 and empty when it has not said.
    int         progress_percent{-1};
    std::string job;
    // Degrees Celsius, as last reported; absent when it has not said.
    std::optional<double> nozzle_temperature;
    std::optional<double> bed_temperature;
};

struct PrinterCandidate
{
    // Opaque, session-local identifier for one model and nozzle variant.
    std::string id;
    std::string vendor_id;
    std::string vendor_name;
    std::string model_id;
    std::string model_name;
    std::string device_model_id;
    std::string variant;
    std::string preset_name;
    std::string build_volume;
    std::string default_material;
    std::string default_plate;
    std::string artwork_path;
};

} // namespace Slic3r::GUI::JusPrin::PrinterSetup
#pragma once

// What the printer conversation is allowed to know and do about printers.
//
// A printer is app-level, not project-level, so this follows Home rather than
// the workspace contract: the surface owns a narrow interface, and one Orca
// implementation behind it calls the existing owners -- PrinterCatalog,
// PrinterDiscovery, Printers::, SetupCommands::. GUI-free and
// Orca-free so the conversation can be tested without either.

#include "PrinterSetupTypes.hpp"

#include <chrono>
#include <optional>
#include <string>
#include <vector>

namespace Slic3r::GUI::JusPrin::PrinterSetup {

// One spool as a connected printer reports it.
struct PrinterSpool
{
    std::string name;
    std::string material;
    std::string colour; // "#RRGGBB", empty when unknown
};

// A printer already saved in this app: an Orca user printer profile, with the
// facts it was set up with.
struct SavedPrinter
{
    std::string               name;
    std::string               device_id;
    std::string               model;        // display model name
    std::string               model_id;     // profile model id
    std::string               vendor_id;
    std::string               picture;      // cover image path, may be empty
    double                    nozzle{0.};
    std::vector<double>       nozzles;      // sizes this model ships
    std::string               plate;        // untranslated plate name
    std::string               ams;          // "AMS lite", "AMS", or empty
    std::vector<PrinterSpool> spools;
    std::string               activity;     // offline, idle, printing, or empty
    bool                      connected{false};
    // One of OrcaSlicer's own printer profiles, selected in the project, not
    // a printer the person saved: nothing is saved on it, and a change to its
    // settings is saved as a copy under `copy_name`, which is then theirs.
    bool                      stock{false};
    std::string               copy_name;
};

// What the packaged profiles offer, one entry per model.
struct CatalogPrinter
{
    std::string         id; // catalogue id, stable for this session
    std::string         vendor_id;
    std::string         vendor_name;  // the brand, as its vendor file names it
    std::string         model_id;     // the profile's own name, which Orca installs by
    std::string         model_name;   // that name with the brand not repeated
    std::string         device_model_id;
    std::string         build_volume; // "180 × 180 × 180 mm"
    std::string         picture;
    std::string         default_plate; // empty: the profile names none
    std::vector<double> nozzles;
    // The machine profile's own default filament for each nozzle size, in
    // the order of `nozzles`; empty where that profile names none.
    std::vector<std::string> filaments;

    std::string display_name() const { return vendor_name + " " + model_name; }
    std::string filament_for(double nozzle) const
    {
        for (std::size_t i = 0; i < nozzles.size() && i < filaments.size(); ++i)
            if (nozzles[i] == nozzle)
                return filaments[i];
        return {};
    }
};

// Everything the app needs to save a printer the person has just agreed to.
struct AddPrinterRequest
{
    std::string vendor_id;
    std::string model_id;
    std::string variant;  // nozzle size as the profile spells it, e.g. "0.4"
    std::string material; // default filament preset, may be empty
    std::string name;     // display name; empty uses the model name
    std::string device_id;    // a discovered printer's id, when this is one
};

// A correction to a printer that already exists. Every field is optional;
// what is left out stays as it is.
struct ChangePrinterRequest
{
    std::string                  name; // the saved printer to change
    std::optional<double>        nozzle;
};

struct ConnectionCandidate
{
    std::string id;
    std::string name;
    std::string address;
    bool lan_mode{false};
};

// How long a connection attempt waits for the printer before it is reported
// as failed. The model is told the same number when an attempt starts.
inline constexpr std::chrono::seconds kConnectionWait{30};

struct PrinterConnectionInfo
{
    std::string provider{"unavailable"};
    std::string state{"not_configured"};
    std::string message;
    std::string device_id;
    std::vector<ConnectionCandidate> candidates;
    std::string address;
    std::string host_type;
    bool signed_in{false};
    bool nozzle_mismatch{false};
    // A Bambu Lab printer, on a computer where Bambu's network plug-in is not
    // installed or not turned on: nothing reaches the printer until it is.
    bool needs_network_plugin{false};
};

struct ManualPrinterResult
{
    bool applied{false};
    std::vector<SavedPrinter> added;
};

class IPrinterBackend
{
public:
    virtual ~IPrinterBackend() = default;

    // Reads. The catalogue is every model a person can add from this panel,
    // in a stable order.
    virtual const std::vector<CatalogPrinter>& catalog() const = 0;
    virtual std::vector<DiscoveredPrinter> network_printers() const = 0;
    virtual std::vector<SavedPrinter>     saved_printers() const = 0;
    // A printer profile OrcaSlicer ships, by its preset name, as a person
    // could pick it; `stock` is set. An empty name when there is none.
    virtual SavedPrinter                  stock_printer(const std::string& name) const = 0;

    // Writes. Each returns an empty string on success, or a message written
    // for the person explaining what stopped it. A change lists the keys of
    // the unsaved edits it dropped from the project's copy in `discarded`.
    virtual std::string add_printer(const AddPrinterRequest& request, SavedPrinter& added) = 0;
    virtual std::string change_printer(const ChangePrinterRequest& request, SavedPrinter& changed,
                                       std::vector<std::string>& discarded) = 0;
    // Deletes a saved printer the way Home's "Remove printer…" does.
    virtual std::string remove_printer(const std::string& name) = 0;

    // The manual paths behind "Set it up myself": OrcaSlicer's own printer
    // wizard for a new printer, its printer settings for an existing one.
    virtual ManualPrinterResult run_manual_setup() = 0;
    virtual void open_printer_settings(const std::string& name) = 0;

    // Connection is a separate operation against an existing saved printer.
    // Credentials are input-only and never part of a snapshot or conversation.
    // connect_printer and connect_host start an attempt and return at once;
    // connection() reports it as connecting until it settles, and a new
    // attempt replaces one still waiting. connect_host saves the address only
    // once the printer has answered.
    virtual PrinterConnectionInfo connection(const std::string& name) { return {}; }
    virtual void prepare_connection(const std::string& name) {}
    virtual void sign_in_to_bambu() {}
    // Downloads and loads Bambu's network plug-in behind Orca's own progress
    // dialog, as Orca's "Click here to install it" does. Returns once that
    // dialog closes, whether or not the plug-in is loaded then.
    virtual void install_network_plugin() {}
    virtual std::string connect_printer(const std::string& name, const std::string& device_id,
                                       const std::string& access_code) { return "Connection is unavailable."; }
    virtual std::string connect_host(const std::string& name, const std::string& host_type,
                                    const std::string& address, const std::string& api_key) { return "Connection is unavailable."; }
    // Abandons this printer's attempt if it is still waiting: whatever the
    // printer answers afterwards is dropped.
    virtual void cancel_connection(const std::string& name) {}
};

} // namespace Slic3r::GUI::JusPrin::PrinterSetup

