 54	const CatalogPrinter* OrcaPrinterBackend::model_of(const std::string& printer_name) const
 55	{
 56	    const PresetBundle* presets = wxGetApp().preset_bundle;
 57	    if (presets == nullptr)
 58	        return nullptr;
 59	    const Preset* preset = presets->printers.find_preset(printer_name, false);
 60	    if (preset == nullptr)
 61	        return nullptr;
 62	    const std::string model = preset->config.opt_string("printer_model");
 63	    const auto        found = std::find_if(m_models.begin(), m_models.end(),
 64	                                           [&model](const CatalogPrinter& printer) { return printer.model_id == model; });
 65	    return found == m_models.end() ? nullptr : &*found;
 66	}
