237	void OrcaPrinterBackend::prepare_connection(const std::string& name)
238	{
239	    const CatalogPrinter* model = model_of(name);
240	    if (model == nullptr || model->vendor_id != "BBL")
241	        return;
242	    NetworkAgent* agent = wxGetApp().getAgent();
243	    const std::string fake = fake_bambu_printer_agent_id(wxGetApp().app_config);
244	    if (agent == nullptr || (fake.empty() && !NetworkAgent::is_network_module_loaded()))
245	        return;
246	    const std::string wanted = fake.empty() ? BBL_PRINTER_AGENT_ID : fake;
247	    if (!agent->get_printer_agent() || agent->get_printer_agent()->get_agent_info().id != wanted) {
248	        // A connection gesture selects the networking provider, not a slicing
249	        // preset. NetworkAgent owns callback transfer and disconnects the old
250	        // provider; the open project's settings and unsaved edits stay intact.
251	        // Orca's profile-driven policy takes the provider back the next time
252	        // the printer profile changes; connecting again reinstalls it.
253	        auto provider = NetworkAgentFactory::create_printer_agent_by_id(
254	            wanted, agent->get_cloud_agent(BBL_CLOUD_PROVIDER), Slic3r::data_dir());
255	        if (!provider)
256	            throw std::runtime_error("The registered Bambu printer agent could not be created");
257	        agent->set_printer_agent(std::move(provider));
258	        wxGetApp().sidebar().update_all_preset_comboboxes();
259	    }
260	    agent->start_discovery(true, false);
261	}
