275	PrinterConnectionInfo OrcaPrinterBackend::connection(const std::string& name)
276	{
277	    PrinterConnectionInfo info;
278	    const auto saved = saved_printers();
279	    const auto printer = std::find_if(saved.begin(), saved.end(), [&](const SavedPrinter& p) { return p.name == name; });
280	    if (printer == saved.end()) {
281	        info.state = "unavailable";
282	        info.message = "This printer was renamed or removed. Open it again from Printers.";
283	        return info;
284	    }
285	    const CatalogPrinter* model = model_of(name);
286	    if (!model || model->vendor_id != "BBL") {
287	        const Preset* preset = wxGetApp().preset_bundle->printers.find_preset(name, false, true);
288	        if (!preset)
289	            throw std::logic_error("A saved printer has no preset");
290	        if (m_host_attempt && m_host_attempt->name == name && m_host_attempt->state == "connecting")
291	            settle(*m_host_attempt);
292	        const auto type = preset->config.opt_enum<PrintHostType>("host_type");
293	        info.address = preset->config.opt_string("print_host");
294	        info.host_type = type == htMoonraker ? "moonraker" : type == htOctoPrint ? "octoprint" : "other";
295	        info.provider = "host";
296	        info.state = info.address.empty() ? "not_configured" : "unknown";
297	        if (info.state == "unknown")
298	            info.message = "A connection is saved. Test it to check access; live printer status is not available here.";
299	        if (info.host_type == "other") {
300	            info.state = "unavailable";
301	            info.message = "Configure this connection type in Printer settings. You can still prepare prints and export a file.";
302	        }
303	        if (m_host_attempt && m_host_attempt->name == name) {
304	            auto& attempt = *m_host_attempt;
305	            // Only a verified attempt saved its settings; it holds while the
306	            // printer is still set up as it was tested.
307	            if (attempt.state == "verified" &&
308	                (info.address != attempt.address || info.host_type != attempt.host_type ||
309	                 preset->config.opt_string("printhost_apikey") != attempt.api_key)) {
310	                info.message = "Connection settings changed. Test the new connection again.";
311	                return info;
312	            }
313	            info.state = attempt.state;
314	            info.message = attempt.message;
315	        }
316	        return info;
317	    }
318	    info.provider = "bambu";
319	    info.device_id = printer->device_id;
320	    auto* devices = wxGetApp().getDeviceManager();
321	    auto* agent = wxGetApp().getAgent();
322	    info.signed_in = agent && agent->is_user_login(BBL_CLOUD_PROVIDER);
323	    if (fake_bambu_printer_agent_id(wxGetApp().app_config).empty() && !NetworkAgent::is_network_module_loaded()) {
324	        info.state = "unavailable";
325	        info.needs_network_plugin = true;
326	        info.message = "Connecting a Bambu Lab printer needs Bambu's network plug-in, which is not installed or not turned on. "
327	                       "The printer can already prepare prints without it.";
328	        return info;
329	    }
330	    if (!devices || !agent) {
331	        info.state = "unavailable";
332	        info.message = "Connecting is not available right now. The printer can already prepare prints.";
333	        return info;
334	    }
335	    auto candidates = devices->get_local_machinelist();
336	    for (const auto& entry : devices->get_my_cloud_machine_list())
337	        candidates[entry.first] = entry.second;
338	    for (const auto& [id, machine] : candidates) {
339	        if (!machine || machine->printer_type != model->device_model_id)
340	            continue;
341	        if (!info.device_id.empty() && id != info.device_id)
342	            continue;
343	        const bool used_elsewhere = std::any_of(saved.begin(), saved.end(), [&](const SavedPrinter& p) {
344	            return p.name != name && p.device_id == id;
345	        });
346	        if (!used_elsewhere && (!machine->is_lan_mode_printer() || machine->is_avaliable()))
347	            info.candidates.push_back({id, machine->get_dev_name(), machine->get_dev_ip(), machine->is_lan_mode_printer()});
348	    }
349	    MachineObject* machine = info.device_id.empty() ? nullptr : devices->get_my_machine(info.device_id);
350	    // is_connected() alone is optimistic immediately after reset(). Require
351	    // actual parsed push data, and fresh LAN data for a LAN connection.
352	    const bool communicating = machine && has_recent_printer_data(*machine);
353	    const bool configured = has_verified_printer_connection(info.device_id);
354	    info.state = communicating ? "verified" : configured ? "unknown" : "not_configured";
355	    if (info.state == "unknown")
356	        info.message = "Connection status is unknown. Check that the printer is on, then reconnect.";
357	    if (m_connection_attempt && m_connection_attempt->name == name) {
358	        const auto& attempt = *m_connection_attempt;
359	        if (info.device_id != attempt.device_id)
360	            throw std::logic_error("A connection attempt lost its saved printer association");
361	        const bool observed = communicating &&
362	            (machine->is_lan_mode_printer() ? machine->last_lan_msg_time_ > attempt.observation_start
363	                                           : machine->last_cloud_msg_time_ > attempt.observation_start);
364	        if (devices->get_selected_machine() != machine && machine != nullptr && !attempt.reselecting) {
365	            info.state = "failed";
366	            info.message = "The selected printer changed. Select this printer again to reconnect.";
367	        } else if (observed) {
368	            info.state = "verified";
369	            m_connection_attempt.reset();
370	        } else if (machine == nullptr) {
371	            info.state = "failed";
372	            info.message = "The printer is no longer available. Refresh the printer list and try again.";
373	        } else if (std::chrono::steady_clock::now() - attempt.started > kConnectionWait) {
374	            info.state = "failed";
375	            info.message = "The printer did not respond. Check that it is on the network and try again.";
376	        } else {
377	            info.state = "connecting";
378	            info.message.clear();
379	        }
380	    }
381	    if (info.state == "verified")
382	        wxGetApp().app_config->set("jusprin_verified_connections", info.device_id, "true");
383	    if (communicating) {
384	        const auto* extruders = machine->GetExtderSystem();
385	        info.nozzle_mismatch = extruders && extruders->GetNozzleDiameter(0) > 0 &&
386	            std::abs(extruders->GetNozzleDiameter(0) - printer->nozzle) > 0.001;
387	    }
388	    return info;
389	}
