391	std::string OrcaPrinterBackend::connect_printer(const std::string& name, const std::string& device_id,
392	                                               const std::string& access_code)
393	{
394	    // The same printer asked for again keeps waiting; anything else replaces
395	    // the attempt below.
396	    if (m_connection_attempt && m_connection_attempt->name == name && m_connection_attempt->device_id == device_id &&
397	        connection(name).state == "connecting")
398	        return {};
399	    const auto info = connection(name);
400	    if (info.provider != "bambu" || info.state == "unavailable")
401	        return info.message;
402	    if (std::none_of(info.candidates.begin(), info.candidates.end(), [&](const ConnectionCandidate& p) { return p.id == device_id; }))
403	        return "Choose a matching printer from the refreshed list.";
404	    auto* devices = wxGetApp().getDeviceManager();
405	    MachineObject* machine = devices->get_my_machine(device_id);
406	    if (!machine)
407	        machine = devices->get_local_machine(device_id);
408	    if (!machine)
409	        return "That printer is no longer available. Refresh the list and try again.";
410	    if (machine->is_lan_mode_printer()) {
411	        if (access_code.empty() && !machine->has_access_right())
412	            return "Enter the access code shown on your printer.";
413	        if (!std::all_of(access_code.begin(), access_code.end(), [](unsigned char c) {
414	                return (c >= '0' && c <= '9') || (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z');
415	            }))
416	            return "The access code can only contain letters and numbers.";
417	    }
418	    const wxString problem = Printers::link_named_printer(name, device_id);
419	    if (!problem.empty())
420	        return problem.ToStdString();
421	    prepare_connection(name);
422	    if (machine->is_lan_mode_printer() && !access_code.empty())
423	        machine->set_user_access_code(access_code);
424	    m_connection_attempt = ConnectionAttempt{name, device_id, std::chrono::steady_clock::now(),
425	                                              std::chrono::system_clock::now()};
426	    if (devices->get_selected_machine() != machine) {
427	        devices->set_selected_machine(device_id);
428	        return {};
429	    }
430	    // Selecting the selected LAN printer again disconnects and reconnects
431	    // it, and GUI_App's local-connect handler hears the disconnect one event
432	    // turn later and clears the selection -- after the reconnect. Deselect
433	    // now, and select it again once that notice has run.
434	    m_connection_attempt->reselecting = true;
435	    devices->set_selected_machine("");
436	    wxGetApp().CallAfter([alive = std::weak_ptr<bool>(m_alive), this, device_id] {
437	        if (alive.expired() || !m_connection_attempt || m_connection_attempt->device_id != device_id)
438	            return;
439	        m_connection_attempt->reselecting = false;
440	        wxGetApp().getDeviceManager()->set_selected_machine(device_id);
441	    });
442	    return {};
443	}
