100	   100	        // its multi-filament unit holds -- nothing, when it has none.
101	   101	        const auto host = Printers::host_status(named.name);
102	   102	        const bool host_answered = host && host->link == Printers::HostLink::Reachable;
103	   103	        if (host_answered)
104	   104	            saved.connected = true;
105	   105	        if (found != network.end() && !saved.device_id.empty()) {
106	   106	            saved.connected = found->connected;
107	   107	            saved.activity  = found->activity == PrinterActivity::Printing ? "printing" :
108	   108	                              found->activity == PrinterActivity::Idle     ? "idle" :
109	   109	                                                                            "offline";
110	   110	            saved.ams       = found->ams_name;
111	   111	            for (const DiscoveredPrinter::Spool& spool : found->spools)
112	   112	                saved.spools.push_back(PrinterSpool{spool.name, spool.material, spool.colour});
113	   113	        } else if (host_answered && host->loaded) {
114	   114	            // The unit names a material, not a product.
115	   115	            for (const Printers::HostLane& lane : *host->loaded)
116	   116	                saved.spools.push_back(PrinterSpool{lane.material, lane.material, lane.colour});
117	   117	        }
118	   118	        // Not connected, or never was: nothing is known to be loaded, and
119	   119	        // nothing is claimed.
120	   120	        printers.push_back(std::move(saved));
121	   121	    }
122	   122	    return printers;
123	   123	}
