 68	std::vector<SavedPrinter> OrcaPrinterBackend::saved_printers() const
 69	{
 70	    const std::vector<DiscoveredPrinter> network = discover_printers(/*include_unreachable=*/true);
 71	    const PresetBundle*                  presets = wxGetApp().preset_bundle;
 72	
 73	    std::vector<SavedPrinter> printers;
 74	    for (const Printers::NamedPrinter& named : Printers::named_printers()) {
 75	        SavedPrinter saved;
 76	        saved.name      = named.name;
 77	        saved.device_id = named.device_id;
 78	        saved.nozzle    = named.nozzle;
 79	
 80	        if (const CatalogPrinter* model = model_of(named.name)) {
 81	            saved.model     = model->display_name();
 82	            saved.model_id  = model->model_id;
 83	            saved.vendor_id = model->vendor_id;
 84	            saved.picture   = model->picture;
 85	            saved.nozzles   = model->nozzles;
 86	            saved.plate     = model->default_plate;
 87	        }
 88	        if (presets != nullptr) {
 89	            if (const Preset* preset = presets->printers.find_preset(named.name, false)) {
 90	                const std::string plate = preset->config.opt_string("default_bed_type");
 91	                if (!plate.empty())
 92	                    saved.plate = plate;
 93	            }
 94	        }
 95	
 96	        // What the machine says beats what the profile assumed.
 97	        const auto found = std::find_if(network.begin(), network.end(),
 98	                                        [&saved](const DiscoveredPrinter& device) { return device.stable_id == saved.device_id; });
 99	        // A Moonraker host that answered lately is connected, and says what
100	        // its multi-filament unit holds -- nothing, when it has none.
101	        const auto host = Printers::host_status(named.name);
102	        const bool host_answered = host && host->link == Printers::HostLink::Reachable;
103	        if (host_answered)
104	            saved.connected = true;
105	        if (found != network.end() && !saved.device_id.empty()) {
106	            saved.connected = found->connected;
107	            saved.activity  = found->activity == PrinterActivity::Printing ? "printing" :
108	                              found->activity == PrinterActivity::Idle     ? "idle" :
109	                                                                            "offline";
110	            saved.ams       = found->ams_name;
111	            for (const DiscoveredPrinter::Spool& spool : found->spools)
112	                saved.spools.push_back(PrinterSpool{spool.name, spool.material, spool.colour});
113	        } else if (host_answered && host->loaded) {
114	            // The unit names a material, not a product.
115	            for (const Printers::HostLane& lane : *host->loaded)
116	                saved.spools.push_back(PrinterSpool{lane.material, lane.material, lane.colour});
117	        }
118	        // Not connected, or never was: nothing is known to be loaded, and
119	        // nothing is claimed.
120	        printers.push_back(std::move(saved));
121	    }
122	    return printers;
123	}
