125	SavedPrinter OrcaPrinterBackend::stock_printer(const std::string& name) const
126	{
127	    SavedPrinter stock;
128	    const PresetBundle* presets = wxGetApp().preset_bundle;
129	    const Preset*       preset  = presets != nullptr ? presets->printers.find_preset(name, false) : nullptr;
130	    if (preset == nullptr || preset->name != name || !preset->is_system || !preset->is_visible)
131	        return stock;
132	    stock.name      = preset->name;
133	    stock.stock     = true;
134	    stock.copy_name = Printers::copy_name(name, [presets](const std::string& candidate) {
135	        return std::any_of(presets->printers.begin(), presets->printers.end(),
136	                           [&candidate](const Preset& preset) { return boost::iequals(preset.name, candidate); });
137	    });
138	    if (const auto* nozzle = preset->config.option<ConfigOptionFloats>("nozzle_diameter"); nozzle && !nozzle->values.empty())
139	        stock.nozzle = nozzle->values.front();
140	    if (const CatalogPrinter* model = model_of(name)) {
141	        stock.model     = model->display_name();
142	        stock.model_id  = model->model_id;
143	        stock.vendor_id = model->vendor_id;
144	        stock.picture   = model->picture;
145	        stock.nozzles   = model->nozzles;
146	        stock.plate     = model->default_plate;
147	    }
148	    return stock;
149	}
