186	std::string OrcaPrinterBackend::change_printer(const ChangePrinterRequest& request, SavedPrinter& changed,
187	                                               std::vector<std::string>& discarded)
188	{
189	    std::vector<SavedPrinter> printers = saved_printers();
190	    const auto                found    = std::find_if(printers.begin(), printers.end(),
191	                                                      [&request](const SavedPrinter& saved) { return saved.name == request.name; });
192	    if (found == printers.end())
193	        return "This app no longer has a printer called \"" + request.name + "\".";
194	
195	    if (request.nozzle) {
196	        const PrinterCandidate* variant = nullptr;
197	        for (const PrinterCandidate& candidate : m_catalog.candidates())
198	            if (candidate.model_id == found->model_id && nozzle_of(candidate.variant) == *request.nozzle)
199	                variant = &candidate;
200	        if (variant == nullptr)
201	            return found->model.empty() ? std::string("This printer does not come with that nozzle size.") :
202	                                          "The " + found->model + " does not come with that nozzle size.";
203	        const wxString problem = Printers::change_named_printer_nozzle(m_plater, request.name, variant->preset_name, discarded);
204	        if (!problem.empty())
205	            return problem.ToStdString();
206	    }
207	
208	    for (const SavedPrinter& saved : saved_printers())
209	        if (saved.name == request.name)
210	            changed = saved;
211	    return {};
212	}
