219	ManualPrinterResult OrcaPrinterBackend::run_manual_setup()
220	{
221	    // OrcaSlicer's own printer wizard, unchanged, and the printers it
222	    // installs are saved under their own names the way the old dialog's
223	    // manual path did.
224	    const Printers::VendorMap before = wxGetApp().app_config->vendors();
225	    // False when the person closed the wizard without applying it.
226	    if (!wxGetApp().run_wizard(ConfigWizard::RR_USER, ConfigWizard::SP_PRINTERS))
227	        return {};
228	    const auto names = Printers::name_installed_printers(m_plater, before);
