275	PrinterConnectionInfo OrcaPrinterBackend::connection(const std::string& name)
276	{
277	    PrinterConnectionInfo info;
278	    const auto saved = saved_printers();
279	    const auto printer = std::find_if(saved.begin(), saved.end(), [&](const SavedPrinter& p) { return p.name == name; });
280	    if (printer == saved.end()) {
281	        info.state = "unavailable";
282	        info.message = "This printer was renamed or removed. Open it again from Printers.";
283	        return info;
284	    }
285	    const CatalogPrinter* model = model_of(name);
286	    if (!model || model->vendor_id != "BBL") {
287	        const Preset* preset = wxGetApp().preset_bundle->printers.find_preset(name, false, true);
288	        if (!preset)
289	            throw std::logic_error("A saved printer has no preset");
290	        if (m_host_attempt && m_host_attempt->name == name && m_host_attempt->state == "connecting")
291	            settle(*m_host_attempt);
292	        const auto type = preset->config.opt_enum<PrintHostType>("host_type");
293	        info.address = preset->config.opt_string("print_host");
294	        info.host_type = type == htMoonraker ? "moonraker" : type == htOctoPrint ? "octoprint" : "other";
295	        info.provider = "host";
296	        info.state = info.address.empty() ? "not_configured" : "unknown";
297	        if (info.state == "unknown")
298	            info.message = "A connection is saved. Test it to check access; live printer status is not available here.";
299	        if (info.host_type == "other") {
300	            info.state = "unavailable";
301	            info.message = "Configure this connection type in Printer settings. You can still prepare prints and export a file.";
302	        }
303	        if (m_host_attempt && m_host_attempt->name == name) {
304	            auto& attempt = *m_host_attempt;
305	            // Only a verified attempt saved its settings; it holds while the
306	            // printer is still set up as it was tested.
307	            if (attempt.state == "verified" &&
308	                (info.address != attempt.address || info.host_type != attempt.host_type ||
309	                 preset->config.opt_string("printhost_apikey") != attempt.api_key)) {
310	                info.message = "Connection settings changed. Test the new connection again.";
311	                return info;
312	            }
313	            info.state = attempt.state;
314	            info.message = attempt.message;
315	        }
316	        return info;
317	    }
318	    info.provider = "bambu";
319	    info.device_id = printer->device_id;
320	    auto* devices = wxGetApp().getDeviceManager();
321	    auto* agent = wxGetApp().getAgent();
322	    info.signed_in = agent && agent->is_user_login(BBL_CLOUD_PROVIDER);
323	    if (fake_bambu_printer_agent_id(wxGetApp().app_config).empty() && !NetworkAgent::is_network_module_loaded()) {
324	        info.state = "unavailable";
325	        info.needs_network_plugin = true;
326	        info.message = "Connecting a Bambu Lab printer needs Bambu's network plug-in, which is not installed or not turned on. "
327	                       "The printer can already prepare prints without it.";
328	        return info;
329	    }
330	    if (!devices || !agent) {
331	        info.state = "unavailable";
332	        info.message = "Connecting is not available right now. The printer can already prepare prints.";
333	        return info;
334	    }
335	    auto candidates = devices->get_local_machinelist();
336	    for (const auto& entry : devices->get_my_cloud_machine_list())
337	        candidates[entry.first] = entry.second;
338	    for (const auto& [id, machine] : candidates) {
339	        if (!machine || machine->printer_type != model->device_model_id)
340	            continue;
341	        if (!info.device_id.empty() && id != info.device_id)
342	            continue;
343	        const bool used_elsewhere = std::any_of(saved.begin(), saved.end(), [&](const SavedPrinter& p) {
344	            return p.name != name && p.device_id == id;
345	        });
346	        if (!used_elsewhere && (!machine->is_lan_mode_printer() || machine->is_avaliable()))
347	            info.candidates.push_back({id, machine->get_dev_name(), machine->get_dev_ip(), machine->is_lan_mode_printer()});
348	    }
349	    MachineObject* machine = info.device_id.empty() ? nullptr : devices->get_my_machine(info.device_id);
350	    // is_connected() alone is optimistic immediately after reset(). Require
351	    // actual parsed push data, and fresh LAN data for a LAN connection.
352	    const bool communicating = machine && has_recent_printer_data(*machine);
353	    const bool configured = has_verified_printer_connection(info.device_id);
354	    info.state = communicating ? "verified" : configured ? "unknown" : "not_configured";
355	    if (info.state == "unknown")
356	        info.message = "Connection status is unknown. Check that the printer is on, then reconnect.";
357	    if (m_connection_attempt && m_connection_attempt->name == name) {
358	        const auto& attempt = *m_connection_attempt;
359	        if (info.device_id != attempt.device_id)
360	            throw std::logic_error("A connection attempt lost its saved printer association");
361	        const bool observed = communicating &&
362	            (machine->is_lan_mode_printer() ? machine->last_lan_msg_time_ > attempt.observation_start
363	                                           : machine->last_cloud_msg_time_ > attempt.observation_start);
364	        if (devices->get_selected_machine() != machine && machine != nullptr && !attempt.reselecting) {
365	            info.state = "failed";
366	            info.message = "The selected printer changed. Select this printer again to reconnect.";
367	        } else if (observed) {
368	            info.state = "verified";
369	            m_connection_attempt.reset();
370	        } else if (machine == nullptr) {
371	            info.state = "failed";
372	            info.message = "The printer is no longer available. Refresh the printer list and try again.";
373	        } else if (std::chrono::steady_clock::now() - attempt.started > kConnectionWait) {
374	            info.state = "failed";
375	            info.message = "The printer did not respond. Check that it is on the network and try again.";
376	        } else {
377	            info.state = "connecting";
378	            info.message.clear();
379	        }
380	    }
381	    if (info.state == "verified")
382	        wxGetApp().app_config->set("jusprin_verified_connections", info.device_id, "true");
383	    if (communicating) {
384	        const auto* extruders = machine->GetExtderSystem();
385	        info.nozzle_mismatch = extruders && extruders->GetNozzleDiameter(0) > 0 &&
386	            std::abs(extruders->GetNozzleDiameter(0) - printer->nozzle) > 0.001;
387	    }
388	    return info;
389	}
390	
391	std::string OrcaPrinterBackend::connect_printer(const std::string& name, const std::string& device_id,
392	                                               const std::string& access_code)
393	{
394	    // The same printer asked for again keeps waiting; anything else replaces
395	    // the attempt below.
396	    if (m_connection_attempt && m_connection_attempt->name == name && m_connection_attempt->device_id == device_id &&
397	        connection(name).state == "connecting")
398	        return {};
399	    const auto info = connection(name);
400	    if (info.provider != "bambu" || info.state == "unavailable")
401	        return info.message;
402	    if (std::none_of(info.candidates.begin(), info.candidates.end(), [&](const ConnectionCandidate& p) { return p.id == device_id; }))
403	        return "Choose a matching printer from the refreshed list.";
404	    auto* devices = wxGetApp().getDeviceManager();
405	    MachineObject* machine = devices->get_my_machine(device_id);
406	    if (!machine)
407	        machine = devices->get_local_machine(device_id);
408	    if (!machine)
409	        return "That printer is no longer available. Refresh the list and try again.";
410	    if (machine->is_lan_mode_printer()) {
411	        if (access_code.empty() && !machine->has_access_right())
412	            return "Enter the access code shown on your printer.";
413	        if (!std::all_of(access_code.begin(), access_code.end(), [](unsigned char c) {
414	                return (c >= '0' && c <= '9') || (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z');
415	            }))
416	            return "The access code can only contain letters and numbers.";
417	    }
418	    const wxString problem = Printers::link_named_printer(name, device_id);
419	    if (!problem.empty())
420	        return problem.ToStdString();
421	    prepare_connection(name);
422	    if (machine->is_lan_mode_printer() && !access_code.empty())
423	        machine->set_user_access_code(access_code);
424	    m_connection_attempt = ConnectionAttempt{name, device_id, std::chrono::steady_clock::now(),
425	                                              std::chrono::system_clock::now()};
426	    if (devices->get_selected_machine() != machine) {
427	        devices->set_selected_machine(device_id);
428	        return {};
429	    }
430	    // Selecting the selected LAN printer again disconnects and reconnects
431	    // it, and GUI_App's local-connect handler hears the disconnect one event
432	    // turn later and clears the selection -- after the reconnect. Deselect
433	    // now, and select it again once that notice has run.
434	    m_connection_attempt->reselecting = true;
435	    devices->set_selected_machine("");
436	    wxGetApp().CallAfter([alive = std::weak_ptr<bool>(m_alive), this, device_id] {
437	        if (alive.expired() || !m_connection_attempt || m_connection_attempt->device_id != device_id)
438	            return;
439	        m_connection_attempt->reselecting = false;
440	        wxGetApp().getDeviceManager()->set_selected_machine(device_id);
441	    });
442	    return {};
443	}
444	
445	std::string OrcaPrinterBackend::connect_host(const std::string& name, const std::string& host_type,
446	                                            const std::string& address, const std::string& api_key)
447	{
448	    const auto info = connection(name);
449	    if (info.provider != "host" || info.state == "unavailable")
450	        return info.message;
451	    if (host_type != "moonraker" && host_type != "octoprint")
452	        return "Choose Moonraker or OctoPrint.";
453	    if (address.empty() || address.find_first_of("\r\n\t @") != std::string::npos)
454	        return "Enter the printer's host name, IP address or HTTP URL without credentials.";
455	    if (address.find("://") != std::string::npos && address.rfind("http://", 0) != 0 && address.rfind("https://", 0) != 0)
456	        return "Use an HTTP or HTTPS address.";
457	    const auto* preset = wxGetApp().preset_bundle->printers.find_preset(name, false, true);
458	    if (!preset)
459	        return "This printer was renamed or removed.";
460	    // Reuse a saved secret only for the same endpoint and provider.
461	    const std::string key = api_key.empty() && address == info.address && host_type == info.host_type ?
462	        preset->config.opt_string("printhost_apikey") : api_key;
463	    // Tested on a copy: the printer's own settings change only once the host
464	    // has answered (settle).
465	    DynamicPrintConfig config = preset->config;
466	    config.set_key_value("host_type", new ConfigOptionEnum<PrintHostType>(host_type == "moonraker" ? htMoonraker : htOctoPrint));
467	    config.set_key_value("print_host", new ConfigOptionString(address));
468	    config.set_key_value("printhost_apikey", new ConfigOptionString(key));
469	    std::unique_ptr<PrintHost> host(PrintHost::get_print_host(&config));
470	    if (!host)
471	        throw std::logic_error("A supported print host has no adapter");
472	    // PrintHost::test blocks until the host answers, and a host that accepts
473	    // the connection and never replies holds it with no upper bound (Http's
474	    // DEFAULT_TIMEOUT_MAX is 0). So it runs on a thread of its own, as
475	    // upstream's upload queue runs these adapters. Nothing waits for it:
476	    // joining could hold the panel's close for as long as the host dawdles,
477	    // and kConnectionWait reports the failure meanwhile. The adapter keeps
478	    // copies of what it read from `config`.
479	    auto verdict = std::make_shared<std::atomic<HostVerdict>>(HostVerdict::Testing);
480	    std::thread([host = std::move(host), verdict] {
481	        wxString detail;
482	        verdict->store(host->test(detail) ? HostVerdict::Passed : HostVerdict::Failed);
483	    }).detach();
484	    m_host_attempt = HostAttempt{name, host_type, address, key, std::chrono::steady_clock::now(), std::move(verdict), "connecting", {}};
485	    return {};
486	}
487	
488	void OrcaPrinterBackend::settle(HostAttempt& attempt)
489	{
490	    switch (attempt.verdict->load()) {
491	    case HostVerdict::Passed: {
492	        const wxString problem = Printers::configure_named_printer_host(
493	            attempt.name, attempt.host_type == "moonraker" ? htMoonraker : htOctoPrint, attempt.address, attempt.api_key);
494	        attempt.state   = problem.empty() ? "verified" : "failed";
495	        attempt.message = problem.ToStdString();
496	        // The test's answer is Home's first word on this host.
497	        if (problem.empty())
498	            Printers::note_host_answered(attempt.name);
499	        break;
500	    }
501	    case HostVerdict::Failed:
502	        attempt.state   = "failed";
503	        attempt.message = "Could not reach the print host. Check its address, API key and network, then try again.";
504	        break;
505	    case HostVerdict::Testing:
506	        if (std::chrono::steady_clock::now() - attempt.started > kConnectionWait) {
507	            attempt.state   = "failed";
508	            attempt.message = "The printer did not respond. Check that it is on the network and try again.";
509	        }
510	        break;
511	    }
512	}
513	
514	void OrcaPrinterBackend::cancel_connection(const std::string& name)
515	{
516	    if (m_host_attempt && m_host_attempt->name == name && m_host_attempt->state == "connecting")
517	        m_host_attempt.reset();
518	    // A Bambu Lab printer stays linked to the device and selected, as after a
519	    // failure; undoing both is separate work.
520	    if (m_connection_attempt && m_connection_attempt->name == name)
521	        m_connection_attempt.reset();
522	}
523	
524	void OrcaPrinterBackend::open_printer_settings(const std::string& name)
525	{
526	    // A stock profile is in a conversation only as the project's selected
527	    // printer, so its settings are the printer tab as it stands.
528	    if (!stock_printer(name).name.empty() && wxGetApp().preset_bundle->printers.get_selected_preset_name() == name) {
529	        SetupCommands::open_settings_tab(Preset::TYPE_PRINTER);
530	        return;
531	    }
532	    Printers::open_named_printer_settings(m_plater, name);
533	}
