    32	std::vector<std::string> split(const std::string& value, char delimiter)
    33	{
    34	    std::vector<std::string> result;
    35	    std::istringstream input(value);
    36	    std::string part;
    37	    while (std::getline(input, part, delimiter))
    38	        if (!part.empty()) result.push_back(part);
    39	    return result;
