    50	json resolve_machine(const std::string& name, const std::map<std::string, json>& machines,
    51	                     std::set<std::string>& visiting)
    52	{
    53	    const auto found = machines.find(name);
    54	    if (found == machines.end() || !visiting.insert(name).second)
    55	        return json::object();
    56	    json resolved = json::object();
    57	    const std::string parent = found->second.value("inherits", "");
    58	    if (!parent.empty())
    59	        resolved = resolve_machine(parent, machines, visiting);
    60	    for (const auto& item : found->second.items())
    61	        resolved[item.key()] = item.value();
    62	    visiting.erase(name);
    63	    return resolved;
    64	}
    65	
    66	std::string build_volume(const json& machine)
    67	{
    68	    const auto area = machine.value("printable_area", json::array());
    69	    double min_x = 0., min_y = 0., max_x = 0., max_y = 0.;
    70	    bool first = true;
    71	    for (const auto& point : area) {
    72	        if (!point.is_string()) continue;
    73	        const auto values = split(point.get<std::string>(), 'x');
    74	        if (values.size() != 2) continue;
    75	        try {
    76	            const double x = std::stod(values[0]);
    77	            const double y = std::stod(values[1]);
    78	            if (first) { min_x = max_x = x; min_y = max_y = y; first = false; }
    79	            else { min_x = std::min(min_x, x); max_x = std::max(max_x, x);
    80	                   min_y = std::min(min_y, y); max_y = std::max(max_y, y); }
    81	        } catch (const std::exception&) {}
    82	    }
    83	    if (first) return {};
    84	    const std::string height = first_string(machine.value("printable_height", json()));
    85	    if (height.empty()) return {};
    86	    auto clean = [](double value) {
    87	        std::ostringstream out;
    88	        out << std::fixed << std::setprecision(value == std::floor(value) ? 0 : 1) << value;
    89	        return out.str();
    90	    };
    91	    return clean(max_x - min_x) + " × " + clean(max_y - min_y) + " × " + height + " mm";
    92	}
