    98	PrinterCatalog PrinterCatalog::load(const std::string& resources_directory)
    99	{
   100	    const fs::path profiles = fs::path(resources_directory) / "profiles";
   101	    std::vector<PrinterCandidate> candidates;
   102	    for (const fs::directory_entry& vendor_entry : fs::directory_iterator(profiles)) {
   103	        if (!vendor_entry.is_regular_file() || vendor_entry.path().extension() != ".json") continue;
   104	        const std::string vendor_id = vendor_entry.path().stem().string();
   105	        const json index = read_json(vendor_entry.path());
   106	        if (!index.contains("machine_model_list") || !index.contains("machine_list")) continue;
   107	        const std::string vendor_name = index.value("name", vendor_id);
   108	        const fs::path vendor_dir = profiles / vendor_id;
   109	
   110	        std::map<std::string, json> machines;
   111	        for (const auto& entry : index["machine_list"]) {
   112	            const std::string name = entry.value("name", "");
   113	            const std::string sub_path = entry.value("sub_path", "");
   114	            if (!name.empty() && !sub_path.empty()) machines.emplace(name, read_json(vendor_dir / sub_path));
   115	        }
   116	
   117	        // Which machine profile is a model's profile for a nozzle size, by
   118	        // what each profile declares rather than by its name: vendors name
   119	        // them "K1 (0.4 nozzle)", "MINIIS 0.4 nozzle" and more.
   120	        std::map<std::pair<std::string, std::string>, std::string> profile_of;
   121	        for (const auto& [name, raw] : machines) {
   122	            std::set<std::string> visiting;
   123	            const json resolved = resolve_machine(name, machines, visiting);
   124	            if (resolved.value("instantiation", "true") == "false") continue;
   125	            const std::string printer_model = first_string(resolved.value("printer_model", json()));
   126	            const std::string printer_variant = first_string(resolved.value("printer_variant", json()));
   127	            if (!printer_model.empty() && !printer_variant.empty())
   128	                profile_of.emplace(std::make_pair(printer_model, printer_variant), name);
   129	        }
   130	
   131	        for (const auto& entry : index["machine_model_list"]) {
   132	            const std::string sub_path = entry.value("sub_path", "");
   133	            if (sub_path.empty()) continue;
   134	            const json model = read_json(vendor_dir / sub_path);
   135	            const std::string model_name = model.value("name", entry.value("name", ""));
   136	            const std::string model_id = model_name;
   137	            const std::string device_model = model.value("model_id", "");
   138	            const auto variants = split(first_string(model.value("nozzle_diameter", json())), ';');
   139	            const std::string plate = first_string(model.value("default_bed_type", json()));
   140	            fs::path artwork = vendor_dir / (model_name + "_cover.png");
   141	            if (!fs::exists(artwork)) artwork.clear();
   142	
   143	            for (const std::string& variant : variants) {
   144	                const auto        declared    = profile_of.find(std::make_pair(model_name, variant));
   145	                const std::string preset_name = declared != profile_of.end() ? declared->second :
   146	                                                                              model_name + " " + variant + " nozzle";
   147	                std::set<std::string> visiting;
   148	                const json machine = resolve_machine(preset_name, machines, visiting);
   149	                if (machine.empty()) continue; // not an installable variant
   150	                PrinterCandidate candidate;
   151	                candidate.id = "printer-" + std::to_string(candidates.size());
   152	                candidate.vendor_id = vendor_id;
   153	                candidate.vendor_name = vendor_name;
   154	                candidate.model_id = model_id;
   155	                candidate.model_name = model_name;
   156	                candidate.device_model_id = device_model;
   157	                candidate.variant = variant;
   158	                candidate.preset_name = preset_name;
   159	                candidate.build_volume = build_volume(machine);
   160	                // OrcaSlicer's own default for this machine profile. Not the
   161	                // model's default_materials: that is the wizard's list of
   162	                // filaments to tick, and its first entry is often not PLA.
   163	                candidate.default_material = first_string(machine.value("default_filament_profile", json()));
   164	                candidate.default_plate = plate;
   165	                candidate.artwork_path = artwork.string();
   166	                candidates.push_back(std::move(candidate));
   167	            }
   168	        }
   169	    }
   170	    if (candidates.empty())
   171	        throw std::runtime_error("No installable printer profiles were found.");
   172	    return PrinterCatalog(std::move(candidates));
   173	}
