   200	std::string letters_and_digits(const std::string& text)
   201	{
   202	    std::string kept;
   203	    for (unsigned char letter : text)
   204	        if (std::isalnum(letter))
   205	            kept.push_back(static_cast<char>(std::tolower(letter)));
