    66	std::string build_volume(const json& machine)
    67	{
    68	    const auto area = machine.value("printable_area", json::array());
    69	    double min_x = 0., min_y = 0., max_x = 0., max_y = 0.;
    70	    bool first = true;
    71	    for (const auto& point : area) {
    72	        if (!point.is_string()) continue;
