   225	// Most profiles repeat the brand at the start of the model's name, often
   226	// spelled better than the vendor file does ("Bambu Lab A1 mini" under
   227	// "Bambulab"). Then the brand is that spelling and the model is the rest;
   228	// otherwise the brand is the vendor file's own name.
   229	std::pair<std::string, std::string> split_brand(const std::string& vendor_name, const std::string& profile_name)
   230	{
   231	    const std::string brand = letters_and_digits(vendor_name);
   232	    // At each word boundary, "Bambu" then "Bambu Lab": the brand may be more
   233	    // than one word.
   234	    for (std::size_t end = profile_name.find(' '); end != std::string::npos && !brand.empty();
   235	         end = profile_name.find(' ', end + 1)) {
   236	        const std::string prefix = letters_and_digits(profile_name.substr(0, end));
   237	        if (prefix.size() > brand.size())
   238	            break;
   239	        if (prefix == brand)
   240	            return {profile_name.substr(0, end), profile_name.substr(end + 1)};
   241	    }
   242	    return {vendor_name, profile_name};
