   245	std::vector<CatalogPrinter> PrinterCatalog::panel_printers() const
   246	{
   247	    // The catalogue carries one candidate per model and nozzle; a person has
   248	    // one printer with one nozzle, so the variants fold into the model and
   249	    // the sizes it ships become a fact about it.
   250	    std::vector<CatalogPrinter> printers;
   251	    for (const PrinterCandidate& candidate : m_candidates) {
   252	        if (candidate.vendor_id == kPanelHiddenVendor)
   253	            continue;
   254	        const std::string id    = candidate.vendor_id + "/" + candidate.model_id;
   255	        const auto  known = std::find_if(printers.begin(), printers.end(),
   256	                                         [&id](const CatalogPrinter& printer) { return printer.id == id; });
   257	        std::size_t index = static_cast<std::size_t>(known - printers.begin());
   258	        if (known == printers.end()) {
   259	            CatalogPrinter printer;
   260	            printer.id              = id;
   261	            printer.vendor_id       = candidate.vendor_id;
   262	            printer.model_id        = candidate.model_id;
   263	            printer.device_model_id = candidate.device_model_id;
   264	            printer.build_volume    = candidate.build_volume;
   265	            printer.picture         = candidate.artwork_path;
   266	            printer.default_plate   = candidate.default_plate;
   267	            name_printer(printer, candidate.vendor_name, candidate.model_name);
   268	            printers.push_back(std::move(printer));
   269	        }
   270	        CatalogPrinter& printer = printers[index];
   271	        const double    nozzle  = nozzle_of(candidate.variant);
   272	        if (nozzle > 0. && std::find(printer.nozzles.begin(), printer.nozzles.end(), nozzle) == printer.nozzles.end()) {
   273	            printer.nozzles.push_back(nozzle);
   274	            printer.filaments.push_back(candidate.default_material);
   275	        }
   276	    }
   277	    for (CatalogPrinter& printer : printers) {
   278	        std::vector<std::size_t> order(printer.nozzles.size());
   279	        for (std::size_t i = 0; i < order.size(); ++i)
   280	            order[i] = i;
   281	        std::sort(order.begin(), order.end(),
   282	                  [&printer](std::size_t lhs, std::size_t rhs) { return printer.nozzles[lhs] < printer.nozzles[rhs]; });
   283	        std::vector<double>      nozzles;
   284	        std::vector<std::string> filaments;
   285	        for (std::size_t i : order) {
   286	            nozzles.push_back(printer.nozzles[i]);
   287	            filaments.push_back(printer.filaments[i]);
   288	        }
   289	        printer.nozzles   = std::move(nozzles);
   290	        printer.filaments = std::move(filaments);
   291	    }
   292	    return printers;
   293	}
