    conversation.start(ConversationMode::Add);
    action(conversation, json{{"action", "manual_setup"}});
    action(conversation, json{{"action", "form_options"}, {"catalogId", "BBL/Bambu Lab A1 mini"}, {"nozzle", 0.4}});
    settle(conversation);
}

