---
name: agent-panel-css-namespaces
description: AgentUI styles.css has no CSS modules — the setup-* class prefix belongs to the agent setup screens, so new components need their own prefix
metadata:
  type: project
---

`src/slic3r/GUI/JusPrin/AgentUI/src/styles.css` is one flat global stylesheet
with no CSS modules or scoping. The `setup-*` prefix is already taken by the
agent **setup screens** (`Setup.tsx`, `SetupLocalTool.tsx`) — `.setup-card`
there is `display: flex; flex-direction: column` on a lavender
`--surface-selected` ground.

**Why:** a new component that reuses one of those names silently inherits
`display: flex` and leaks its own rules back onto the setup screens. This cost
real time once: the "Current setup" card reused `.setup-card`, which defeated
its `white-space: nowrap` title clamp and re-tinted its background. Both
suites stayed green — jsdom does no layout, so no unit test can see it.

**How to apply:** pick a prefix that does not already appear in styles.css
(`grep -n '^\.<prefix>' src/styles.css`), and verify layout by rendering the
real component at real width rather than trusting tests. The pattern that
works: `SetupCard.preview.test.tsx` uses `renderToStaticMarkup` plus the real
styles.css and design tokens to emit a page of every state, served over a
local http server and measured in the browser (`scrollWidth > clientWidth`,
row heights). See [[render-widget-to-bitmap-for-visual-proof]].
// Guards the stylesheet's contract with resources/jusprin/ui/design-tokens.json:
// colors, radii, and type metrics resolve through the custom properties that
// tokens.ts emits, and spacing sits on the spacing scale. The file is read
// from disk on purpose: importing the CSS under Vitest yields an empty string,
// so a test written that way passes while asserting nothing.

import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { describe, expect, it } from 'vitest';
import { semanticVariableNames } from '@shared/tokens';
import { staticVariableNames } from './tokens';

const SPACING_SCALE = [0, 4, 8, 12, 16, 20, 24, 32, 40, 48];

const source = readFileSync(join(__dirname, 'styles.css'), 'utf8');

// Blank out comments but keep every newline so reported line numbers match
// the file.
const css = source.replace(/\/\*[\s\S]*?\*\//g, (comment) => comment.replace(/[^\n]/g, ' '));
const lines = css.split('\n');

// Line numbers (1-based) covered by an @font-face block, where font metrics
// are the declaration of the face itself rather than a use of it.
function fontFaceLines(): Set<number> {
  const covered = new Set<number>();
  let depth = 0;
  let inFontFace = false;
  lines.forEach((line, index) => {
    if (!inFontFace && /@font-face\b/.test(line)) inFontFace = true;
    if (inFontFace) covered.add(index + 1);
    for (const ch of line) {
      if (ch === '{') depth += 1;
      if (ch === '}') {
        depth -= 1;
        if (inFontFace && depth === 0) inFontFace = false;
      }
    }
  });
  return covered;
}

const exemptLines = fontFaceLines();

function offending(pattern: RegExp, extra?: (line: string) => boolean): string[] {
  const hits: string[] = [];
  lines.forEach((line, index) => {
    const number = index + 1;
    if (exemptLines.has(number)) return;
    if (pattern.test(line) && (!extra || extra(line))) hits.push(`${number}: ${line.trim()}`);
  });
  return hits;
}

describe('styles.css stays on the design tokens', () => {
  it('was actually read', () => {
    expect(source.trim().length).toBeGreaterThan(0);
  });

  it('carries no literal color', () => {
    expect(offending(/#[0-9a-fA-F]{3,8}\b|\b(rgba?|hsla?)\(/)).toEqual([]);

